-- 세트 365: Git 기록 살펴보기: log 옵션, 파일·작성자로 거르기, show, diff, blame
-- 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다. docs/specs/spec_git_history_set.md
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (365, 1, '기록 한 줄씩 훑어보기', '`/tmp/lab/proj` 는 Git 저장소입니다. 지금까지의 커밋을 **한 줄에 하나씩(해시 약식 + 제목)** 보여 주는 명령의 출력을 **`/tmp/lab/log_all.txt`** 에 저장하세요.', '`git log` 는 커밋 기록을 보여 줍니다. 한 줄 요약 옵션을 붙이면 훨씬 짧아집니다. 저장소 폴더로 이동하거나 `git -C 폴더 ...` 를 쓰세요.', 'cd /tmp/lab/proj
git log --oneline > /tmp/lab/log_all.txt
cat /tmp/lab/log_all.txt

# --oneline : 커밋을 한 줄씩', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\necho ''print(\\"hello wrld\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''print(\\"hello world\\")'' > app.py; git add app.py; c ''fix greeting typo'' Bob 3\\necho ''write tests'' > todo.txt; git add todo.txt; c ''add todo list'' Ann 4\\ngit mv app.py main.py; c ''rename app.py to main.py'' Bob 5\\necho ''print(\\"hello world v2\\")'' > main.py; git add main.py; c ''bump version to v2'' Ann 6\\necho ''one more line'' >> README.md\\necho ''add docs'' >> todo.txt; git add todo.txt\\ntrue"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/lab/log_all.txt)\\" -ge 6 ] && [ \\"$(cat /tmp/lab/log_all.txt)\\" = \\"$(git -C /tmp/lab/proj log --oneline)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "log_all.txt 가 한 줄 요약 6줄과 같다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/lab/log_all.txt)\\" -ge 6 ] && [ \\"$(cat /tmp/lab/log_all.txt)\\" = \\"$(git -C /tmp/lab/proj log --oneline)\\" ]"]}]', '[{"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git diff 문서", "url": "https://git-scm.com/docs/git-diff"}, {"title": "git show 문서", "url": "https://git-scm.com/docs/git-show"}, {"title": "git blame 문서", "url": "https://git-scm.com/docs/git-blame"}]'),
  (365, 2, '최근 커밋만 보기', '가장 **최근 커밋 2개**만 한 줄 요약으로 **`/tmp/lab/log_two.txt`** 에 저장하세요.', '`git log` 에는 보여 줄 개수를 `-숫자` 로 줄이는 방법이 있습니다.', 'cd /tmp/lab/proj
git log --oneline -2 > /tmp/lab/log_two.txt
cat /tmp/lab/log_two.txt

# -2 : 최근 2개', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\necho ''print(\\"hello wrld\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''print(\\"hello world\\")'' > app.py; git add app.py; c ''fix greeting typo'' Bob 3\\necho ''write tests'' > todo.txt; git add todo.txt; c ''add todo list'' Ann 4\\ngit mv app.py main.py; c ''rename app.py to main.py'' Bob 5\\necho ''print(\\"hello world v2\\")'' > main.py; git add main.py; c ''bump version to v2'' Ann 6\\necho ''one more line'' >> README.md\\necho ''add docs'' >> todo.txt; git add todo.txt\\ntrue"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/lab/log_two.txt)\\" -eq 2 ] && [ \\"$(cat /tmp/lab/log_two.txt)\\" = \\"$(git -C /tmp/lab/proj log --oneline -2)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "log_two.txt 가 정확히 최근 2개 한 줄 요약이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/lab/log_two.txt)\\" -eq 2 ] && [ \\"$(cat /tmp/lab/log_two.txt)\\" = \\"$(git -C /tmp/lab/proj log --oneline -2)\\" ]"]}]', '[{"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git diff 문서", "url": "https://git-scm.com/docs/git-diff"}, {"title": "git show 문서", "url": "https://git-scm.com/docs/git-show"}, {"title": "git blame 문서", "url": "https://git-scm.com/docs/git-blame"}]'),
  (365, 3, '작성자로 거르기', '작성자가 `Bob` 인 커밋만 한 줄 요약으로 **`/tmp/lab/by_bob.txt`** 에 저장하세요.', '`git log` 에 작성자 이름으로 거르는 옵션이 있습니다. `옵션=값` 형태입니다.', 'cd /tmp/lab/proj
git log --oneline --author=Bob > /tmp/lab/by_bob.txt
cat /tmp/lab/by_bob.txt

# --author=이름 : 그 작성자의 커밋만', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\necho ''print(\\"hello wrld\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''print(\\"hello world\\")'' > app.py; git add app.py; c ''fix greeting typo'' Bob 3\\necho ''write tests'' > todo.txt; git add todo.txt; c ''add todo list'' Ann 4\\ngit mv app.py main.py; c ''rename app.py to main.py'' Bob 5\\necho ''print(\\"hello world v2\\")'' > main.py; git add main.py; c ''bump version to v2'' Ann 6\\necho ''one more line'' >> README.md\\necho ''add docs'' >> todo.txt; git add todo.txt\\ntrue"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/lab/by_bob.txt)\\" -eq 2 ] && [ \\"$(cat /tmp/lab/by_bob.txt)\\" = \\"$(git -C /tmp/lab/proj log --oneline --author=Bob)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "by_bob.txt 가 Bob 의 커밋 2줄과 같다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/lab/by_bob.txt)\\" -eq 2 ] && [ \\"$(cat /tmp/lab/by_bob.txt)\\" = \\"$(git -C /tmp/lab/proj log --oneline --author=Bob)\\" ]"]}]', '[{"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git diff 문서", "url": "https://git-scm.com/docs/git-diff"}, {"title": "git show 문서", "url": "https://git-scm.com/docs/git-show"}, {"title": "git blame 문서", "url": "https://git-scm.com/docs/git-blame"}]'),
  (365, 4, '한 파일의 기록만 보기', '파일 `todo.txt` 를 바꾼 **커밋만** 한 줄 요약으로 **`/tmp/lab/todo_log.txt`** 에 저장하세요. (아직 기록하지 않은 변경은 커밋이 아니므로 나오지 않습니다.)', '`git log` 뒤에 `--` 와 경로를 쓰면 그 경로를 바꾼 커밋만 나옵니다.', 'cd /tmp/lab/proj
git log --oneline -- todo.txt > /tmp/lab/todo_log.txt
cat /tmp/lab/todo_log.txt

# -- 파일 : 그 파일을 바꾼 커밋만', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\necho ''print(\\"hello wrld\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''print(\\"hello world\\")'' > app.py; git add app.py; c ''fix greeting typo'' Bob 3\\necho ''write tests'' > todo.txt; git add todo.txt; c ''add todo list'' Ann 4\\ngit mv app.py main.py; c ''rename app.py to main.py'' Bob 5\\necho ''print(\\"hello world v2\\")'' > main.py; git add main.py; c ''bump version to v2'' Ann 6\\necho ''one more line'' >> README.md\\necho ''add docs'' >> todo.txt; git add todo.txt\\ntrue"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/lab/todo_log.txt)\\" -eq 1 ] && [ \\"$(cat /tmp/lab/todo_log.txt)\\" = \\"$(git -C /tmp/lab/proj log --oneline -- todo.txt)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "todo_log.txt 가 todo.txt 를 바꾼 커밋 1줄과 같다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/lab/todo_log.txt)\\" -eq 1 ] && [ \\"$(cat /tmp/lab/todo_log.txt)\\" = \\"$(git -C /tmp/lab/proj log --oneline -- todo.txt)\\" ]"]}]', '[{"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git diff 문서", "url": "https://git-scm.com/docs/git-diff"}, {"title": "git show 문서", "url": "https://git-scm.com/docs/git-show"}, {"title": "git blame 문서", "url": "https://git-scm.com/docs/git-blame"}]'),
  (365, 5, '이름이 바뀌어도 이어서 따라가기', '`main.py` 는 예전에 `app.py` 였습니다. 이름이 바뀌기 전 기록까지 **이어서** 따라가며 `main.py` 의 커밋을 한 줄 요약으로 **`/tmp/lab/main_history.txt`** 에 저장하세요. (이름을 따라가지 않으면 이름이 바뀐 뒤의 커밋만 나옵니다.)', '`git log` 에 파일 이름 변경을 따라가는 옵션이 있습니다. 파일 경로는 `--` 뒤에 씁니다.', 'cd /tmp/lab/proj
git log --oneline --follow -- main.py > /tmp/lab/main_history.txt
cat /tmp/lab/main_history.txt

# --follow : 이름이 바뀌기 전 기록까지 따라간다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\necho ''print(\\"hello wrld\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''print(\\"hello world\\")'' > app.py; git add app.py; c ''fix greeting typo'' Bob 3\\necho ''write tests'' > todo.txt; git add todo.txt; c ''add todo list'' Ann 4\\ngit mv app.py main.py; c ''rename app.py to main.py'' Bob 5\\necho ''print(\\"hello world v2\\")'' > main.py; git add main.py; c ''bump version to v2'' Ann 6\\necho ''one more line'' >> README.md\\necho ''add docs'' >> todo.txt; git add todo.txt\\ntrue"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/lab/main_history.txt)\\" -eq 4 ] && [ \\"$(cat /tmp/lab/main_history.txt)\\" = \\"$(git -C /tmp/lab/proj log --oneline --follow -- main.py)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "main_history.txt 가 이름 변경 전까지 포함한 4줄과 같다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/lab/main_history.txt)\\" -eq 4 ] && [ \\"$(cat /tmp/lab/main_history.txt)\\" = \\"$(git -C /tmp/lab/proj log --oneline --follow -- main.py)\\" ]"]}]', '[{"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git diff 문서", "url": "https://git-scm.com/docs/git-diff"}, {"title": "git show 문서", "url": "https://git-scm.com/docs/git-show"}, {"title": "git blame 문서", "url": "https://git-scm.com/docs/git-blame"}]'),
  (365, 6, '한 커밋에서 바뀐 파일 이름만 보기', '가장 최근 커밋(`HEAD`)에서 **바뀐 파일의 이름만** (다른 설명 없이) **`/tmp/lab/changed.txt`** 에 저장하세요.', '`git show` 는 커밋 한 개의 내용을 보여 줍니다. 파일 이름만 보는 옵션과, 커밋 설명 줄을 비우는 `--format=` (값 없음)를 함께 쓰면 이름만 남습니다.', 'cd /tmp/lab/proj
git show --name-only --format= HEAD > /tmp/lab/changed.txt
cat /tmp/lab/changed.txt

# --name-only : 바뀐 파일 이름만, --format= : 커밋 설명 줄을 뺀다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\necho ''print(\\"hello wrld\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''print(\\"hello world\\")'' > app.py; git add app.py; c ''fix greeting typo'' Bob 3\\necho ''write tests'' > todo.txt; git add todo.txt; c ''add todo list'' Ann 4\\ngit mv app.py main.py; c ''rename app.py to main.py'' Bob 5\\necho ''print(\\"hello world v2\\")'' > main.py; git add main.py; c ''bump version to v2'' Ann 6\\necho ''one more line'' >> README.md\\necho ''add docs'' >> todo.txt; git add todo.txt\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/lab/changed.txt)\\" = \\"main.py\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "changed.txt 가 main.py 한 줄이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/lab/changed.txt)\\" = \\"main.py\\" ]"]}]', '[{"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git diff 문서", "url": "https://git-scm.com/docs/git-diff"}, {"title": "git show 문서", "url": "https://git-scm.com/docs/git-show"}, {"title": "git blame 문서", "url": "https://git-scm.com/docs/git-blame"}]'),
  (365, 7, '고친 것과 올려 둔 것을 나눠 보기', '작업 폴더에는 **스테이징하지 않은 변경**(`README.md`)과 **스테이징한 변경**(`todo.txt`)이 섞여 있습니다. (1) 스테이징 **전** 변경의 diff 를 **`/tmp/lab/unstaged.txt`** 에, (2) 스테이징 **된** 변경의 diff 를 **`/tmp/lab/staged.txt`** 에 저장하세요.', '`git diff` 는 기본으로 작업 폴더와 스테이징 영역을 비교합니다. 스테이징된 쪽을 보려면 옵션을 하나 더 붙입니다.', 'cd /tmp/lab/proj
git diff > /tmp/lab/unstaged.txt
git diff --staged > /tmp/lab/staged.txt
cat /tmp/lab/unstaged.txt /tmp/lab/staged.txt

# git diff : 아직 add 안 한 변경, git diff --staged : add 한 변경', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\necho ''print(\\"hello wrld\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''print(\\"hello world\\")'' > app.py; git add app.py; c ''fix greeting typo'' Bob 3\\necho ''write tests'' > todo.txt; git add todo.txt; c ''add todo list'' Ann 4\\ngit mv app.py main.py; c ''rename app.py to main.py'' Bob 5\\necho ''print(\\"hello world v2\\")'' > main.py; git add main.py; c ''bump version to v2'' Ann 6\\necho ''one more line'' >> README.md\\necho ''add docs'' >> todo.txt; git add todo.txt\\ntrue"]', '["sh", "-c", "( [ -s /tmp/lab/unstaged.txt ] && [ \\"$(cat /tmp/lab/unstaged.txt)\\" = \\"$(git -C /tmp/lab/proj diff)\\" ] ) && ( [ -s /tmp/lab/staged.txt ] && [ \\"$(cat /tmp/lab/staged.txt)\\" = \\"$(git -C /tmp/lab/proj diff --staged)\\" ] ) && ( ! cmp -s /tmp/lab/unstaged.txt /tmp/lab/staged.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "unstaged.txt 가 git diff 와 같다 (README.md 변경)", "cmd": ["sh", "-c", "[ -s /tmp/lab/unstaged.txt ] && [ \\"$(cat /tmp/lab/unstaged.txt)\\" = \\"$(git -C /tmp/lab/proj diff)\\" ]"]}, {"label": "staged.txt 가 git diff --staged 와 같다 (todo.txt 변경)", "cmd": ["sh", "-c", "[ -s /tmp/lab/staged.txt ] && [ \\"$(cat /tmp/lab/staged.txt)\\" = \\"$(git -C /tmp/lab/proj diff --staged)\\" ]"]}, {"label": "두 파일의 내용이 서로 다르다", "cmd": ["sh", "-c", "! cmp -s /tmp/lab/unstaged.txt /tmp/lab/staged.txt"]}]', '[{"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git diff 문서", "url": "https://git-scm.com/docs/git-diff"}, {"title": "git show 문서", "url": "https://git-scm.com/docs/git-show"}, {"title": "git blame 문서", "url": "https://git-scm.com/docs/git-blame"}]'),
  (365, 8, '두 커밋 비교하기', '바로 앞 커밋(`HEAD~1`)과 최신 커밋(`HEAD`) 사이에서 `main.py` 가 어떻게 바뀌었는지의 diff 를 **`/tmp/lab/between.txt`** 에 저장하세요.', '`git diff 커밋1 커밋2 -- 파일` 은 두 커밋 사이의 차이를 보여 줍니다. `HEAD~1` 은 HEAD 의 바로 앞 커밋입니다.', 'cd /tmp/lab/proj
git diff HEAD~1 HEAD -- main.py > /tmp/lab/between.txt
cat /tmp/lab/between.txt

# git diff 커밋1 커밋2 : 두 커밋 사이의 차이', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\necho ''print(\\"hello wrld\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''print(\\"hello world\\")'' > app.py; git add app.py; c ''fix greeting typo'' Bob 3\\necho ''write tests'' > todo.txt; git add todo.txt; c ''add todo list'' Ann 4\\ngit mv app.py main.py; c ''rename app.py to main.py'' Bob 5\\necho ''print(\\"hello world v2\\")'' > main.py; git add main.py; c ''bump version to v2'' Ann 6\\necho ''one more line'' >> README.md\\necho ''add docs'' >> todo.txt; git add todo.txt\\ntrue"]', '["sh", "-c", "( [ -s /tmp/lab/between.txt ] && [ \\"$(cat /tmp/lab/between.txt)\\" = \\"$(git -C /tmp/lab/proj diff HEAD~1 HEAD -- main.py)\\" ] ) && ( grep -qF \\"+print(\\\\\\"hello world v2\\\\\\")\\" /tmp/lab/between.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "between.txt 가 HEAD~1 과 HEAD 의 main.py diff 와 같다", "cmd": ["sh", "-c", "[ -s /tmp/lab/between.txt ] && [ \\"$(cat /tmp/lab/between.txt)\\" = \\"$(git -C /tmp/lab/proj diff HEAD~1 HEAD -- main.py)\\" ]"]}, {"label": "diff 에 v2 로 바뀐 줄이 들어 있다", "cmd": ["sh", "-c", "grep -qF \\"+print(\\\\\\"hello world v2\\\\\\")\\" /tmp/lab/between.txt"]}]', '[{"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git diff 문서", "url": "https://git-scm.com/docs/git-diff"}, {"title": "git show 문서", "url": "https://git-scm.com/docs/git-show"}, {"title": "git blame 문서", "url": "https://git-scm.com/docs/git-blame"}]'),
  (365, 9, '그 줄을 누가 바꿨나 (blame)', '`main.py` 의 각 줄을 **마지막으로 바꾼 커밋과 작성자**와 함께 보여 주는 명령의 출력을 **`/tmp/lab/blame.txt`** 에 저장하세요.', '`git blame 파일` 은 줄마다 마지막으로 바꾼 커밋 해시, 작성자, 날짜를 앞에 붙여 보여 줍니다.', 'cd /tmp/lab/proj
git blame main.py > /tmp/lab/blame.txt
cat /tmp/lab/blame.txt

# git blame : 줄마다 마지막으로 바꾼 커밋과 작성자', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\necho ''print(\\"hello wrld\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''print(\\"hello world\\")'' > app.py; git add app.py; c ''fix greeting typo'' Bob 3\\necho ''write tests'' > todo.txt; git add todo.txt; c ''add todo list'' Ann 4\\ngit mv app.py main.py; c ''rename app.py to main.py'' Bob 5\\necho ''print(\\"hello world v2\\")'' > main.py; git add main.py; c ''bump version to v2'' Ann 6\\necho ''one more line'' >> README.md\\necho ''add docs'' >> todo.txt; git add todo.txt\\ntrue"]', '["sh", "-c", "( [ -s /tmp/lab/blame.txt ] && [ \\"$(cat /tmp/lab/blame.txt)\\" = \\"$(git -C /tmp/lab/proj blame main.py)\\" ] ) && ( grep -q Ann /tmp/lab/blame.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "blame.txt 가 git blame main.py 와 같다", "cmd": ["sh", "-c", "[ -s /tmp/lab/blame.txt ] && [ \\"$(cat /tmp/lab/blame.txt)\\" = \\"$(git -C /tmp/lab/proj blame main.py)\\" ]"]}, {"label": "작성자 Ann 이 보인다", "cmd": ["sh", "-c", "grep -q Ann /tmp/lab/blame.txt"]}]', '[{"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git diff 문서", "url": "https://git-scm.com/docs/git-diff"}, {"title": "git show 문서", "url": "https://git-scm.com/docs/git-show"}, {"title": "git blame 문서", "url": "https://git-scm.com/docs/git-blame"}]'),
  (365, 10, 'git show HEAD 는 무엇을 보여 줄까', '`git show HEAD` 를 실행하면 무엇이 나올까요?', '`log` 가 여러 커밋의 목록이라면, `show` 는 한 개를 자세히 보여 줍니다.', NULL, NULL, '[]', 'choice', '["작업 폴더에서 아직 add 하지 않은 변경 전체", "가장 최근 커밋 한 개의 메시지와 그 커밋에서 바뀐 내용", "원격 저장소에 있는 모든 브랜치의 목록", "커밋 전체의 개수와 작성자별 통계"]', 1, '`git show 커밋` 은 그 커밋의 메시지와 바뀐 내용(diff)을 보여 줍니다. `HEAD` 는 현재 가리키는 가장 최근 커밋입니다. 아직 add 하지 않은 변경은 `git diff`, 브랜치 목록은 `git branch -a`, 개수·통계는 `git shortlog -sn` 으로 봅니다.', NULL, NULL, NULL, '[{"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git diff 문서", "url": "https://git-scm.com/docs/git-diff"}, {"title": "git show 문서", "url": "https://git-scm.com/docs/git-show"}, {"title": "git blame 문서", "url": "https://git-scm.com/docs/git-blame"}]'),
  (365, 11, '커밋 메시지로 찾기', '메시지에 `version` 이 들어 있는 커밋만 한 줄 요약으로 찾는 명령입니다. 빈칸을 채우세요.', '메시지 안의 글자로 거르는 옵션이에요. 영어 단어 하나로 되어 있어요.', NULL, NULL, '[]', 'fill', '["grep", "find", "search", "message"]', NULL, '`git log --grep=패턴` 은 커밋 메시지에서 패턴이 들어 있는 커밋만 보여 줍니다. 작성자로 거르는 `--author`, 경로로 거르는 `-- 파일` 과 구분해서 기억하세요.', '[0]', 'git log --{0}=version --oneline', NULL, '[{"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git diff 문서", "url": "https://git-scm.com/docs/git-diff"}, {"title": "git show 문서", "url": "https://git-scm.com/docs/git-show"}, {"title": "git blame 문서", "url": "https://git-scm.com/docs/git-blame"}]'),
  (365, 12, '고친 뒤 기록하기 전에 확인하는 순서', '파일을 고친 뒤 커밋하기 전에, 무엇이 바뀌었는지 확인하며 진행하는 일반적인 순서입니다. 순서에 맞게 놓아 보세요.', '현황 → 고친 내용 → 올릴 것 고르기 → 올린 내용 확인 → 기록 순서예요.', NULL, NULL, '[]', 'order', '["`git status` 로 바뀐 파일을 본다", "`git diff` 로 고친 내용을 본다", "`git add` 로 기록할 파일을 고른다", "`git diff --staged` 로 올려 둔 내용을 확인한다", "`git commit` 으로 기록한다"]', NULL, '먼저 `status` 로 현황을 보고, `diff` 로 고친 내용을 확인한 뒤, `add` 로 기록할 것을 고르고, `diff --staged` 로 올려 둔 내용을 한 번 더 확인하고 `commit` 합니다.', '[0, 1, 2, 3, 4]', NULL, NULL, '[{"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git diff 문서", "url": "https://git-scm.com/docs/git-diff"}, {"title": "git show 문서", "url": "https://git-scm.com/docs/git-show"}, {"title": "git blame 문서", "url": "https://git-scm.com/docs/git-blame"}]');
